local config = {
  ui_story_5058_50580101_1_dialog_content = "\"คุณเป็นอย่างไรบ้างเพื่อนเก่า? ฉันไม่ได้ยินข่าวจากคุณนานเเล้ว\"",
  ui_story_5058_50580101_2_dialog_content = "\"ฉันยังเหมือนเดิม ดังที่คุณรู้ว่าเราทหารรับจ้างได้รับงานที่แปลกๆ มากมาย\"",
  ui_story_5058_50580101_3_dialog_content = "\"ไม่มีเวลาว่างมากในมือฉัน แต่แค่สามารถวาดเส้นสองสามเส้นต่อวันก็เพียงพอสำหรับฉัน\"",
  ui_story_5058_50580101_4_dialog_content = "\"เพียงแค่ฉันยังไม่ได้พบใครที่มีความสนใจในแมลงเหมือนคุณเท่านั้นเอง\"",
