  ui_story_5058_50580101_6_dialog_content = "\"แต่ผมพูดเพ้อเจ้อ ฉันได้ยินข่าวเกี่ยวกับผีเสื้อที่เรียกว่า <color=#FFB400>เทพีดีนูโอ</color> ในช่วงนี้\"",
