  ui_story_5058_50580101_10_dialog_content = "\"แม้ว่าคุณจะไม่เคยเปิดเผยให้ฉันทราบความเชื่อมโยงระหว่างพวกเขากับเมืองบ้านที่ลึกลับของคุณ...\"",
