  ui_story_5058_50580101_67_dialog_content = "ทุกอย่างที่คุณกำลังมองหาอยู่ในหุบเขา Denuo คุณดูเหมือนว่าใจร้อนอยากไปที่นั่น งั้นเร็วๆ ขึ้นรถมินิบัสกันเถอะ!",
  ui_story_5058_50580101_68_dialog_content = "ยิ่งเราไปถึงเร็วเท่าไหร่ ก็ยิ่งสามารถเริ่มสนุกได้เร็วขึ้น ฉันพูดถูกไหม?",
  ui_story_5058_50580101_69_dialog_content = "เอาเข้าใจเถอะ อย่าทำหน้าเหมือนจะคลื่นไส้ก่อนที่จะขึ้นรถเลยนะ! ขอให้ทราบว่าทุกคนชอบการขับของฉันนะ",
  ui_story_5058_50580101_70_dialog_content = "โอ้ อีกอย่างนะ... หันมาทางนี้ค่ะ แขกรับเชิญท่าน แล้วพูดว่า \"ชีส!\"",
  ui_story_5058_50580101_71_dialog_content = "หา?",
  ui_story_5058_50580101_72_dialog_content = "คุณต้องถ่ายรูปเพื่อระลึกถึงการพักผ่อนนะ!",
  ui_story_5058_50580101_73_dialog_content = "นี่คือความรอบคอบ... ฉันรู้สึกว่าเราจะมีเวลาที่ดีที่นี่!",
