  ui_story_5058_50580101_78_dialog_content = "เอ่อ... นั่น... นั่นเป็นการขับขี่ \"เยี่ยม\" ที่คุณกล่าวถึงใช่ไหม?",
  ui_story_5058_50580101_79_dialog_content = "ลา-ลา-ลา, ลา-ตา-ตา-ลา-ลา... ♪",
  ui_story_5058_50580101_80_dialog_content = "มันคือที่ไหนน่ะ?",
  ui_story_5058_50580101_81_dialog_content = "ลา-ลา-ลา, ลา-ตา-ตา-ลา-ลา ♪ รีสอร์ตเดนูโอ้ วัลลีย์ ยินดีต้อนรับคุณ ♪",
